VALUES ('song-r1', '衍', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '微子启之弟，继兄镇守宋地，为西周时期宋国第二代国君，世次见《史记·宋微子世家》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/微仲"}]'::jsonb, NULL, NULL, '微仲')
