VALUES ('song-r2', '稽', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '微仲之后，宋国早期君主，世次承续而事迹疏略，属西周中叶宋国世君，殷商后裔封国之一。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/稽"}]'::jsonb, NULL, NULL, '稽')
