VALUES ('song-r3', '申', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '宋国第三代君主，谥丁公，在位约二十四年，承微子之封，为西周时期宋国世系中继之君。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋丁公"}]'::jsonb, '丁公', NULL, '宋丁公')
