VALUES ('song-r4', '共', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '丁公之后，谥湣公，在位约二十四年，宋国早期君主，除世次外史料仅存于《史记·宋微子世家》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋湣公"}]'::jsonb, '湣公', NULL, '宋湣公')
