VALUES ('song-r5', '熙', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '湣公之子，谥炀公，在位约二十四年，《史记》载为伯振之父，世系承续宋国嫡系，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋炀公"}]'::jsonb, '炀公', NULL, '宋炀公')
