VALUES ('song-r7', '举', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '纠弑厉公后立，谥釐公，在位约二十八年，复正嫡系，为宋国西周后期重要世君，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋釐公"}]'::jsonb, '釐公', NULL, '宋釐公')
