VALUES ('song-r8', '覵', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '釐公之子，谥惠公，在位三十余年，属西周晚期宋国君主，事迹除世次外记载有限，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋惠公"}]'::jsonb, '惠公', NULL, '宋惠公')
