VALUES ('song-r9', '哀公', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '惠公之子，谥哀公，在位仅一年即卒，为宋国世系中罕见的极短祚君主，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋哀公"}]'::jsonb, '哀公', NULL, '宋哀公')
