VALUES ('song-r10', '白', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '哀公之子，谥戴公，在位三十四年，为春秋初年以前宋国在位时间较长之君，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋戴公"}]'::jsonb, '戴公', NULL, '宋戴公')
