VALUES ('song-r11', '司空', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '戴公之子司空，谥武公，在位十八年，承续宋国嫡系，事迹记载疏略，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋武公"}]'::jsonb, '武公', NULL, '宋武公')
