VALUES ('song-r12', '力', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '武公之子，谥宣公，欲传位弟穆公和，临终仍以长子与夷嗣位，开宋国传弟之先河，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋宣公"}]'::jsonb, '宣公', NULL, '宋宣公')
