VALUES ('song-r13', '和', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '宣公弟子和，为报兄恩拒受传位，后受托孤而立殇公与夷，穆公托孤酿成日后政乱，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋穆公"}]'::jsonb, '穆公', NULL, '宋穆公')
