VALUES ('song-r14', '与夷', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '宣公长子与夷，年幼继位谥殇公，大夫华元弑君并杀孔父嘉，立庄公冯，孔父之难由此而起。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋殇公"}]'::jsonb, '殇公', NULL, '宋殇公')
