VALUES ('song-r15', '冯', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '弑殇公自立，乘丘之战败鲁军、擒南宫长万又释归，前692年因博戏争执，为万弑于蒙泽。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋庄公"}]'::jsonb, '庄公', NULL, '宋庄公')
