VALUES ('song-r17', '游', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '南宫长万弑闵公后立公子游，旋即为诸公子攻杀，在位仅数月，宋国政局再度动荡，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/游"}]'::jsonb, NULL, NULL, '游')
