VALUES ('song-r18', '御说', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '闵公弟御说杀子游自立，谥桓公，会盟诸侯、援齐灭郕，使宋国在春秋初年渐成东方强国。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋桓公"}]'::jsonb, '桓公', NULL, '宋桓公')
