VALUES ('song-r19', '兹甫', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '桓公次子兹甫，谥襄公，泓水之战坚持不击半渡、不擒二毛而败于楚，部分史料列为春秋五霸之一。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋襄公"}]'::jsonb, '襄公', NULL, '宋襄公')
