VALUES ('song-r20', '王臣', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '襄公之子王臣，谥成公，即位后大夫华氏作乱，赖晋救宋方得平定，在位约十七年，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋成公"}]'::jsonb, '成公', NULL, '宋成公')
