VALUES ('song-r21', '御', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '成公弟御弑兄自立，旋即为大夫攻杀，在位仅一年，宋国再度因篡弑而政局不稳，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/御"}]'::jsonb, NULL, NULL, '御')
