VALUES ('song-r22', '杵臼', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '成公之子杵臼，谥昭公，在位八年，其弟鲍革结党弑兄自立，为文公夺位之先声，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋昭公"}]'::jsonb, '昭公', NULL, '宋昭公')
