VALUES ('song-r23', '鲍革', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '鲍革弑兄昭公自立，谥文公，任用公子鲍为政，与楚国结盟，在位约二十一年，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋文公"}]'::jsonb, '文公', NULL, '宋文公')
