VALUES ('song-r24', '瑕', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '文公之子瑕，谥共公，在位十二年，承续文公政局，宋国已渐失春秋强国地位，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋共公"}]'::jsonb, '共公', NULL, '宋共公')
