VALUES ('song-r25', '成', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '共公之子成，谥平公，在位四十三年，为宋国在位最久之君之一，《左传》多有提及，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋平公"}]'::jsonb, '平公', NULL, '宋平公')
