VALUES ('song-r27', '头曼', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '元公之子头曼，谥景公，在位四十七年，倚仗大夫谐音能，国政日衰而内乱仍频，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋景公"}]'::jsonb, '景公', NULL, '宋景公')
