VALUES ('song-r29', '购由', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '战国初君主，谥悼公，在位约十九年，宋国已沦为中小诸侯，事迹除世次外记载有限，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋悼公"}]'::jsonb, '悼公', NULL, '宋悼公')
