VALUES ('song-r30', '田', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '悼公之子田，谥休公，在位约二十一年，属战国早期宋国世君，国势卑微，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋休公"}]'::jsonb, '休公', NULL, '宋休公')
