VALUES ('song-r31', '辟兵', ARRAY[]::text[], '子', '宋', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '休公之子辟兵，谥桓公，在位六年，与春秋宋桓公易混，为战国中期短暂在位之君，事见《史记》本国世家记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/宋桓公"}]'::jsonb, '桓公', NULL, '宋桓公')
